/**
 * 控制列插件基類
 *
 * 提供所有控制列插件共用的功能：
 * - DOM 元素創建和管理
 * - 按順序插入元素
 * - 事件監聽和自動清理
 * - 生命週期管理
 *
 * 設計理念：
 * - 基於 Component 基類，但針對控制列插件優化
 * - 消除重複的 insertByOrder、cleanupFns 等代碼
 * - 提供更簡潔的 API 給插件開發者
 */

import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';
import type { PluginInstance } from '../../core/types/plugin';

/**
 * 控制列位置
 */
export type ControlPosition = 'left' | 'right' | 'progress';

/**
 * 控制列插件基礎配置
 */
export interface ControlPluginOptions {
    /** 按鈕位置：left、right 或 progress（進度條區域） */
    position?: ControlPosition;
    /** 插入順序（數字越小越前面） */
    order?: number;
}

/**
 * 控制列插件抽象基類
 *
 * 使用方式：
 * ```typescript
 * export class MyButtonManager extends ControlPlugin<MyPluginOptions> {
 *     readonly name = 'myButton';
 *
 *     protected createEl(): HTMLElement {
 *         const btn = document.createElement('button');
 *         btn.className = 'vp-btn vp-my-btn';
 *         btn.innerHTML = '<img src="icons/my.svg" />';
 *
 *         // 使用基類方法綁定事件（自動清理）
 *         this.on(btn, 'click', () => this.handleClick());
 *
 *         return btn;
 *     }
 * }
 * ```
 */
export abstract class ControlPlugin<T extends ControlPluginOptions = ControlPluginOptions>
    implements PluginInstance {
    /** 插件名稱（唯一標識） */
    abstract readonly name: string;

    /** 播放器實例引用 */
    protected player: MpvVideoElement;

    /** 根 DOM 元素 */
    protected el: HTMLElement | null = null;

    /** 插件配置 */
    protected options: Required<T>;

    /** 清理函數列表（事件監聯、狀態訂閱等） */
    private cleanups: Array<() => void> = [];

    /** 是否已銷毀 */
    private destroyed = false;

    constructor(player: MpvVideoElement, options: Required<T>) {
        this.player = player;
        this.options = options;
        console.log(`[ControlPlugin] Constructing plugin, player:`, player, 'shadowRoot:', player?.shadowRoot);
        this.initialize();
    }

    /**
     * 初始化插件（由構造函數調用）
     * 子類可以覆蓋此方法添加額外的初始化邏輯
     */
    protected initialize(): void {
        this.el = this.createEl();
        console.log(`[ControlPlugin] Created element:`, this.el);
        if (this.el) {
            this.insertElement();
            console.log(`[ControlPlugin] Element inserted, parent:`, this.el?.parentElement);
        }
    }

    /**
     * 子類必須實現：創建根 DOM 元素
     * 在此方法中創建 DOM 結構並綁定事件
     */
    protected abstract createEl(): HTMLElement | null;

    // ===== 容器查詢 =====

    /**
     * 獲取控制列容器元素
     * @param position - 位置，默認使用 options.position
     */
    protected getControlsContainer(position?: ControlPosition): Element | null {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return null;

        const pos = position ?? this.options.position;

        switch (pos) {
            case 'left':
                return shadowRoot.querySelector('.vp-controls-left');
            case 'right':
                return shadowRoot.querySelector('.vp-controls-right');
            case 'progress':
                return shadowRoot.querySelector('.vp-progress-section');
            default:
                return null;
        }
    }

    // ===== 元素插入 =====

    /**
     * 按順序將元素插入到容器中
     * 使用 data-order 屬性確定位置
     */
    protected insertElement(): void {
        if (!this.el) return;

        const container = this.getControlsContainer();
        if (!container) return;

        // 設置 order 屬性
        this.el.dataset.order = String(this.options.order);

        this.insertByOrder(container, this.el);
    }

    /**
     * 按順序插入元素到容器
     * @param container - 容器元素
     * @param element - 要插入的元素
     */
    protected insertByOrder(container: Element, element: HTMLElement): void {
        const order = parseInt(element.dataset.order || '999', 10);
        const children = Array.from(container.children) as HTMLElement[];

        // 找到第一個 order 比當前大的元素
        const insertBefore = children.find(child => {
            const childOrder = parseInt(child.dataset.order || '999', 10);
            return childOrder > order;
        });

        if (insertBefore) {
            container.insertBefore(element, insertBefore);
        } else {
            container.appendChild(element);
        }
    }

    // ===== 事件監聯（自動清理） =====

    /**
     * 監聯 DOM 事件（自動在銷毀時清理）
     * @param target - 事件目標
     * @param event - 事件名稱
     * @param handler - 事件處理器
     * @param options - 事件選項
     */
    protected on<K extends keyof HTMLElementEventMap>(
        target: HTMLElement | Window | Document,
        event: K,
        handler: (e: HTMLElementEventMap[K]) => void,
        options?: AddEventListenerOptions
    ): void {
        console.log(`[ControlPlugin] Binding DOM event '${event}' on:`, target);
        target.addEventListener(event, handler as EventListener, options);
        this.cleanups.push(() =>
            target.removeEventListener(event, handler as EventListener, options)
        );
    }

    /**
     * 監聯播放器事件（自動在銷毀時清理）
     * @param event - 事件名稱
     * @param handler - 事件處理器
     */
    protected onPlayer(
        event: string,
        handler: EventListenerOrEventListenerObject
    ): void {
        console.log(`[ControlPlugin] Binding player event '${event}' on:`, this.player);
        this.player.addEventListener(event, handler);
        this.cleanups.push(() => this.player.removeEventListener(event, handler));
    }

    /**
     * 註冊清理函數（在銷毀時執行）
     * @param cleanup - 清理函數
     */
    protected registerCleanup(cleanup: () => void): void {
        this.cleanups.push(cleanup);
    }

    // ===== 定時器（自動清理） =====

    /**
     * 設置 setTimeout（自動在銷毀時清理）
     */
    protected setTimeout(callback: () => void, delay: number): number {
        const id = window.setTimeout(callback, delay);
        this.cleanups.push(() => clearTimeout(id));
        return id;
    }

    /**
     * 設置 setInterval（自動在銷毀時清理）
     */
    protected setInterval(callback: () => void, interval: number): number {
        const id = window.setInterval(callback, interval);
        this.cleanups.push(() => clearInterval(id));
        return id;
    }

    // ===== 顯示/隱藏 =====

    /**
     * 顯示插件元素
     */
    enable(): void {
        if (this.el) {
            this.el.style.display = '';
        }
    }

    /**
     * 隱藏插件元素
     */
    disable(): void {
        if (this.el) {
            this.el.style.display = 'none';
        }
    }

    // ===== 生命週期 =====

    /**
     * 銷毀插件
     * 清理所有資源、事件監聯和 DOM 元素
     */
    destroy(): void {
        if (this.destroyed) return;
        this.destroyed = true;

        // 執行所有清理函數
        for (const cleanup of this.cleanups) {
            try {
                cleanup();
            } catch (error) {
                console.error(`[${this.name}] Cleanup error:`, error);
            }
        }
        this.cleanups = [];

        // 移除 DOM 元素
        this.el?.remove();
        this.el = null;
    }

    /**
     * 是否已銷毀
     */
    isDestroyed(): boolean {
        return this.destroyed;
    }

    /**
     * 獲取根元素
     */
    getEl(): HTMLElement | null {
        return this.el;
    }
}
